sys_script_include.script:
var WFSPMCMSConfidentialUtils = Class.create();
WFSPMCMSConfidentialUtils.prototype = {
    initialize: function() {},

    hasConfidentialAccess: function(dmnGr) {
        var group = dmnGr.u_group;
        var groupStr = '';
        if (!gs.nil(group)) {
            groupStr = group.split(",");
        }

        for (var i = 0; i < groupStr.length; i++) {
            if (gs.getUser().isMemberOf(groupStr[i])) {
                gs.getInfoMessages(groupStr);
                return true;
            }
        }
        return false;

    },

    isValidStakeholder: function(usr) {
        var gr = new GlideRecord('dmn_m2m_demand_stakeholder');
        gr.addQuery('stakeholder.user.sys_id', usr);
        gr.query();
        gr.setLimit(1);
        if (gr.next()) {
			gs.addInfoMessage(gr.stakeholder.user.getDisplayValue());
            return true;
        }
        false;

    },
    type: 'WFSPMCMSConfidentialUtils'
};
